BRUTE_FORCE_S = 0.01
CAP = 1000

def compile_filter(db, neg, ctx):
    if not ctx.tenant_id or not ctx.principals:
        return AclFilter(ctx.tenant_id, [], [], 0, match_nothing=True)   # fail closed
    groups = [r[0] for r in db.execute(
        "SELECT group_id FROM user_groups WHERE tenant_id=%s AND user_id=%s", (ctx.tenant_id, ctx.user_id))]
    p = set(ctx.principals) | set(groups)
    p -= neg.revoked(ctx.tenant_id)                  # subtract revoked before anything else
    if ctx.agent_scope is not None:
        p &= ctx.agent_scope                         # an agent never exceeds its scope
    if not p:
        return AclFilter(ctx.tenant_id, [], [], ctx.acl_version, match_nothing=True)
    refs = []
    if len(p) > CAP:                                 # collapse to group references
        refs, p = sorted(p)[CAP:], set(sorted(p)[:CAP])
    return AclFilter(ctx.tenant_id, sorted(p), refs, ctx.acl_version, match_nothing=False)

def search(db, f, qvec, k, stats):
    if f.match_nothing:
        return []
    s = stats.selectivity(f)                         # allowed chunks / total chunks
    if s < BRUTE_FORCE_S:                            # tricky part: tiny allowed set, scan exactly
        sql = ("SELECT chunk_id FROM chunk c JOIN object_acl a USING (tenant_id, doc_id) "
               "WHERE c.tenant_id=%s AND a.principals && %s ORDER BY c.embedding <=> %s LIMIT %s")
        db.execute("SET LOCAL enable_indexscan = off")   # force the exact scan over the allowed rows
    else:
        sql = ("SELECT chunk_id FROM chunk c JOIN object_acl a USING (tenant_id, doc_id) "
               "WHERE c.tenant_id=%s AND a.principals && %s ORDER BY c.embedding <=> %s LIMIT %s")
        db.execute("SET LOCAL hnsw.iterative_scan = relaxed_order")   # check current docs for the pgvector version
    return db.execute(sql, (f.tenant_id, f.principals, qvec, k)).fetchall()

