import time, json, threading

class Node:
    def __init__(self, redis, db, pull_s=5):
        self.r, self.db, self.pull_s = redis, db, pull_s
        self.local, self.last = {}, 0.0

    def _pull(self):
        rows = self.db.execute("SELECT tenant_id, principal_id, scope, until_version FROM revocation").fetchall()
        self.local = {(t, p, s): v for t, p, s, v in rows}
        self.last = time.monotonic()

    def revoked(self, tenant):
        if time.monotonic() - self.last > self.pull_s:   # tricky part: a missed push self-heals in 5 s
            self._pull()
        return {p for (t, p, s) in self.local if t == tenant}

    def listen(self):
        ps = self.r.pubsub()
        ps.subscribe("revoke")
        for m in ps.listen():
            if m["type"] == "message":
                d = json.loads(m["data"])
                self.local[(d["tenant"], d["principal"], d["scope"])] = d["until_version"]
                self.last = time.monotonic()

def revoke(db, redis, tenant, principal, scope, until_version):
    db.execute('''INSERT INTO revocation(tenant_id,principal_id,scope,until_version) VALUES (%s,%s,%s,%s)
                  ON CONFLICT (tenant_id,principal_id,scope) DO UPDATE SET until_version=EXCLUDED.until_version, revoked_at=now()''',
               (tenant, principal, scope, until_version))
    redis.publish("revoke", json.dumps({"tenant": tenant, "principal": principal, "scope": scope, "until_version": until_version}))

def retire(db, tenant, scope, applied_version):
    db.execute("DELETE FROM revocation WHERE tenant_id=%s AND scope=%s AND until_version <= %s", (tenant, scope, applied_version))

