CREATE TABLE access_audit (
  tenant_id text NOT NULL,
  seq bigint NOT NULL,
  row_json jsonb NOT NULL,
  prev_hash text NOT NULL,
  row_hash text NOT NULL,
  at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, seq)
);
CREATE FUNCTION audit_immutable() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'audit rows are append-only'; END $$ LANGUAGE plpgsql;
CREATE TRIGGER audit_no_change BEFORE UPDATE OR DELETE ON access_audit FOR EACH ROW EXECUTE FUNCTION audit_immutable();

