import hashlib, json

def canonical(rec):
    return json.dumps(rec, sort_keys=True, separators=(",", ":"), ensure_ascii=True)

def salted(salt, text):
    return hashlib.sha256((salt + text).encode()).hexdigest()

def append_audit(db, salt, tenant, rec):
    rec = dict(rec)
    rec["query"] = salted(salt, rec["query"])        # no raw query text in the log
    rec["objects"] = [salted(salt, u) for u in rec["objects"]]
    with db.transaction():
        row = db.execute("SELECT seq, row_hash FROM access_audit WHERE tenant_id=%s ORDER BY seq DESC LIMIT 1 FOR UPDATE",
                         (tenant,)).fetchone()
        seq, prev = (row[0] + 1, row[1]) if row else (1, "0" * 64)   # tricky part: lock keeps seq gap-free
        body = canonical(rec)
        h = hashlib.sha256((prev + body).encode()).hexdigest()
        db.execute("INSERT INTO access_audit(tenant_id,seq,row_json,prev_hash,row_hash) VALUES (%s,%s,%s,%s,%s)",
                   (tenant, seq, body, prev, h))
    return seq

def verify_chain(db, tenant):
    prev, expect = "0" * 64, 1
    for seq, body, p, h in db.execute("SELECT seq,row_json::text,prev_hash,row_hash FROM access_audit WHERE tenant_id=%s ORDER BY seq", (tenant,)):
        if seq != expect or p != prev:
            return seq
        if hashlib.sha256((prev + canonical(json.loads(body))).encode()).hexdigest() != h:
            return seq
        prev, expect = h, expect + 1
    return None

