def gate(ctx, chunks):
    kept, drops = [], Counter()
    for c in chunks:
        if c.tenant_id != ctx.tenant or c.zone is None:
            drops["missing_or_tenant"] += 1; continue
        if c.zone == "personal" and c.owner_id != ctx.user_id:
            drops["other_user"] += 1; continue
        if c.zone not in ctx.allowed_zones:
            drops["zone"] += 1; continue
        kept.append(c)
    audit(ctx, len(kept), drops)
    return GateResult(kept, drops)

