def card_visible(ctx, card_id, asker):
    srcs = ctx.lineage.sources(card_id)
    if not srcs or any(ctx.deleted(s) for s in srcs if not ctx.excluded(card_id, s)):
        return False                                   # deleted source authorises no one
    return all(ctx.acl.can_read(asker, s) for s in srcs if not ctx.excluded(card_id, s))
